window.TEXTP["45.0"] = [{"front":true,"blocks":[["f","Мухаммад Махмуд Аль Худайр",{"a":"c","z":15,"mt":146.6}],["f","<b>Идеология тафуида</b>",{"a":"c","z":25,"mt":87.4}],["f","2020",{"a":"c","z":10,"mt":220.7}]],"notes":[]},{"front":true,"blocks":[["f","УДК 2",{"a":"l","z":9,"mt":51.3}],["f","ББК 86",{"a":"l","z":9}],["f","М92",{"a":"l","z":9}],["f","Шрифты предоставлены компанией «ПараТайп»",{"a":"c","z":9,"mt":28.8}],["f","<b>Мухаммад Махмуд Аль Худайр</b>",{"a":"l","z":9,"mt":18.5}],["f","М92 Идеология тафуида / Мухаммад Махмуд Аль Худайр. — [б. м.] :",{"a":"c","z":9}],["f","[б. и.], 2020. — 582 с.",{"a":"l","z":9}],["f","[б. н.]",{"a":"l","z":9}],["f","Данная книга является опровержением труда «Совершенные слова» современного проповедника тафуида — Сейфа аль-Асри т. к. он имеет определённую попу-",{"a":"l","z":7.2,"mt":9.86}],["f","лярность среди русскоязычных сторонников тафуида и ашаризма в целом.",{"a":"c","z":7.2}],["f","Данная книга является научной и является подспорьем для научных дискуссий.",{"a":"l","z":7.2}],["f","<b>УДК 2</b>",{"a":"r","z":9,"mt":9.4}],["f","<b>ББК 86</b>",{"a":"r","z":9}],["f","12+ В соответствии с ФЗ от 29.12.2010 №436-ФЗ",{"a":"l","z":9,"mt":13.1}],["f","© Мухаммад Махмуд Аль Худайр, 2020",{"a":"l","z":9,"mt":213}]],"notes":[]},{"blocks":[["p","<b>ОГЛАВЛЕНИЕ</b>"],["toc","От издательства",{"mt":1.4,"pg":"8"}],["toc","Предисловие",{"pg":"11"}],["toc","Убеждения первых поколений мусульман",{"pg":"17"}],["toc","О книге «Совершенные слова»",{"pg":"19"}],["toc","Методология исследования",{"pg":"20"}],["toc","<b>Убеждения первых поколений мусульман относительно атрибутов Аллаха</b>",{"pg":"23"}],["toc","Единственный источник познания атрибутов Аллаха — божественное откровение",{"pg":"25"}],["toc","Позиция первых поколений мусульман к священным текстам",{"pg":"28"}],["toc","Подтверждение действий Аллаха",{"pg":"36"}],["toc","Доказательства",{"pg":"37"}],["toc","Единогласие общины",{"pg":"39"}],["toc","Подход ко всем атрибутам Аллаха един",{"pg":"41"}],["toc","Ответ на обвинение в антропоморфизме",{"pg":"42"}],["toc","Примеры использования этого правила учёными",{"pg":"44"}],["toc","Ответ на возражения оппонентов",{"pg":"47"}],["toc","Передача текстов об атрибутах на их явном смысле",{"pg":"57"}],["toc","Что имеется в виду под явным смыслом",{"pg":"58"}],["toc","Ранние учёные передавали священные тексты на их явном смысле",{"pg":"61"}],["toc","Общая основа смысла и полный смысл",{"pg":"67"}],["toc","Общая основа смысла",{"pg":"68"}],["toc","Отличительная часть смысла",{"pg":"75"}],["toc","Позиция суннитов к неоднозначным терминам",{"pg":"86"}],["toc","<b>Идеология тафуида</b>",{"pg":"89"}],["toc","Тафуид и его распространение",{"pg":"91"}],["toc","Возникновение тафуида",{"pg":"99"}],["toc","Основы тафуида",{"pg":"104"}],["toc","Позиция рационалистов к шариатским текстам",{"pg":"106"}],["toc","Предпочтение разума над священными текстами",{"pg":"109"}]],"notes":[]},{"blocks":[["toc","Убеждение рационалистов в том, что явный смысл некоторых текстов содержит в себе уподобление Аллаха",{"pg":"113"}],["toc","<b>Непричастность первых поколений мусульман к тафуиду</b>",{"pg":"127"}],["toc","Доказательства несостоятельности тафуида",{"pg":"129"}],["toc","Опровержение доводов оппонентов",{"pg":"155"}],["toc","Ответ на аргументацию аятом «Нет ничего равного Ему» (42:11)",{"pg":"155"}],["toc","Непоследовательность аль-Асри в вопросе общей основы смысла",{"pg":"160"}],["toc","Опровержение этого безосновательного деления атрибутов Аллаха",{"pg":"161"}],["toc","Ответ на аргументацию аятом «Скажи: „Он — Аллах — один“» (112:1)",{"pg":"165"}],["toc","Ответ на аргументацию аятом «Их толкование знает только Аллах» (3:7)",{"pg":"169"}],["toc","Ответ на аргументацию единогласным мнением",{"pg":"178"}],["toc","Ответ на обвинение в приписывании Аллаху тела",{"pg":"183"}],["toc","Ответ на требование разъяснить смысл атрибутов",{"pg":"200"}],["toc","Граница Аллаха",{"pg":"207"}],["toc","Нахождение Аллаха в стороне",{"pg":"216"}],["toc","Непричастность мусульман первых поколений к тафуиду",{"pg":"221"}],["toc","Разъяснение некоторых слов ранних учёных, в которых кто-то может усмотреть тафуид",{"pg":"225"}],["toc","Цитаты ранних учёных и их последователей, содержащие в себе подтверждение смысла атрибутов Аллаха",{"pg":"245"}],["toc","<b>Непричастность Ибн Таймии и Ибн аль-Кайима к обвинениям в их адрес</b>",{"pg":"467"}],["toc","Ибн Таймия явно отрицает подобие Аллаха",{"pg":"470"}],["toc","Ложность истории Ибн Баттуты",{"pg":"474"}],["toc","Ибн аль-Кайим явно отрицает подобие Аллаха",{"pg":"476"}],["toc","Непричастность двух шейхов к приписыванию Аллаху тела",{"pg":"478"}],["toc","Ибн Таймия явно отрицает от Аллаха телесность",{"pg":"478"}],["toc","Ибн аль-Кайим явно отрицает от Аллаха тело",{"pg":"486"}]],"notes":[]},{"blocks":[["toc","Непричастность двух шейхов к приписыванию Аллаху конечностей",{"pg":"492"}],["toc","Ибн Таймия явно отрицает от Аллаха конечности",{"pg":"492"}],["toc","Ибн аль-Кайим явно отрицает от Аллаха конечности",{"pg":"501"}],["toc","Защита некоторыми учёными двух шейхов от обвинения в уподоблении Аллаха творениям и приписывании Ему тела",{"pg":"504"}],["toc","Приложение 1",{"pg":"515"}],["toc","Приложение 2 Замкнутый круг доказательств",{"pg":"518"}],["toc","Ознакомление",{"pg":"518"}],["toc","Опровержение",{"pg":"519"}],["toc","Приложение 3 Аргумент «акциденций и тварности тел»",{"pg":"524"}],["toc","Ознакомление",{"pg":"524"}],["toc","Последствия",{"pg":"528"}],["toc","Опровержение",{"pg":"529"}],["toc","Приложение 4 «Аргумент сочленения»",{"pg":"541"}],["toc","Ознакомление",{"pg":"541"}],["toc","Опровержение",{"pg":"547"}],["toc","Приложение 5 Попытка рационалистов объяснить причину употребления в священных текстах слов, ведущих к антропоморфизму",{"pg":"560"}],["toc","Приложение 6 Связь между аллегорическим толкованием и тафуидом",{"pg":"573"}],["toc","Заключение",{"pg":"580"}]],"notes":[]},{"n":7,"side":"c","blocks":[["c","С именем Аллаха, Милостивого, Милосердного"]],"notes":[]},{"n":8,"side":"c","blocks":[["p","<b>ОТ ИЗДАТЕЛЬСТВА</b>",{"mt":4.44}],["p","Вниманию читателя представлен перевод книги доктора Мухаммада Махмуда Аль Худайра «Идеология тафуида между первыми поколениями общины и рациональными богословами. Опровержение книги „Совершенные слова в установлении тафуида как идеологии первых поколений общины“». К переводу данного труда нас побудила острая необходимость в качественном научном опровержении развивающейся сегодня идеологии тафуида. Книга доктора Аль Худайра полностью отвечает данному критерию и была издана как нельзя кстати. Автор поставил себе целью сделать опровержение книге «Совершенные слова» современного проповедника тафуида — Сейфа аль-Асри, что также послужило дополнительным стимулом для перевода именно данной книги на русский язык, так как аль-Асри имеет определённую популярность среди русскоязычных сторонников тафуида и ашаризма в целом.",{"mt":1.4}],["p","В виду особенностей оригинального текста, нами были внесены некоторые незначительные изменения. Вот некоторые из них:"],["p","• Порядок глав был немного изменён для последовательности изложения."],["p","• Некоторые главы, не имеющие первостепенного значения и тяжёлые к восприятию, были вынесены в приложение а качестве дополнительного чтения."],["p","• Местами текст выражен не буквально, а по смыслу, в том числе и в цитатах."],["p","• Некоторые части текста, имеющие сугубо научное узконаправленное содержимое, были опущены: цепочки передатчиков сообщения, ссылки на редкие, малоизвестные источники, уточнения."],["p","• Были опущены ссылки автора на другие главы своей же книги."]],"notes":[]},{"n":9,"head":"ИДЕОЛОГИЯ ТАФУИДА","side":"c","blocks":[["p","• Порядок слов и предложений мог быть изменён."],["p","• Некоторые части цитат могли быть пропущены, чаще всего, без указания на это многоточием, чтобы текст был более читабельным."],["p","• Некоторые повторения одной и той же мысли или одного и того же понятия, выраженного синонимами, могли быть опущены. В арабском языке это распространённый риторический приём. Однако, на русском языке это зачастую выглядит излишним повторением, затрудняющим восприятие."],["p","Отдельного упоминания заслуживают возражения оппонентов, направленные на автора книги, которые уже были высказаны ими. Суть их заключается в том, что автор ошибочно отнёс некоторых поздних учёных к подтверждавшим смысл атрибутов Аллаха, неверно поняв их терминологию. Нам эти претензии видятся не чем иным, как чёрной риторикой — прибежищем неспособных предоставить веские доказательства, в силу следующих причин:",{"mt":1.31}],["p","• Главная цель обеих книг — выяснить убеждения первых поколений общины, а претензии оппонентов не касаются цитат ранних учёных. Что касается поздних, то нет такой уж большой беды в том, чтобы неправильно их понять, даже если это на самом деле имело место. В данной книге их высказывания были приведены потому, что автор «Совершенных слов» некоторых из них ошибочно отнёс к сторонникам тафуида, что и нуждалось в опровержении."],["p","• Ни одна из книг, написанных людьми, не может быть без ошибок. Если автор опровержения ошибся лишь в этом, то это не является принципиальным недостатком, дискредитирующим книгу полностью. Если убрать из неё цитаты тех учёных, позиция которых вызывает споры, это не будет большой потерей."],["p","• Тем не менее, эти цитаты были оставлены, чтобы они могли послужить основанием для дальнейшего ведения дискуссии. Автор привёл их и попытался обосновать своё понимание. Несогласные могут попытаться оспорить его тезисы, приведя"]],"notes":[]},{"n":10,"head":"МУХАММАД МАХМУД АЛЬ ХУДАЙР","side":"c","blocks":[["c","контраргументы, а безосновательными заявлениями спор не решится."],["p","• Даже если ошибка автора будет доказана, обсуждаемые цитаты послужат свидетельством того, насколько идеология оппонентов запутана, непоследовательна и противоречива. И пусть читатель призадумается: хочет ли он принимать позицию тех, чьи убеждения даже понять трудно."],["p","Несмотря на наши попытки максимально упростить текст, дабы расширить круг читателей, всё же книга не предназначена для начинающих. Предполагается, что читатель приступит к чтению этого исследования, уже имея достаточный багаж знаний. Он должен знать основы убеждений приверженцев Сунны в данной области знаний, определения, термины и основы отклонившихся течений. Этим мы не хотим отвратить читателей от этого труда, но лишь побуждаем к упорядоченному и последовательному изучению исламской доктрины.",{"mt":1.31}],["p","Просим Аллаха принести пользу от этой книги нам, её автору и читателям.",{"mt":1.31}]],"notes":[]},{"n":11,"side":"c","blocks":[["p","<b>ПРЕДИСЛОВИЕ</b>",{"mt":4.44}],["p","Хвала Аллаху, просим Его о помощи и прощении, прибегаем к Нему от зла нас самих и наших злодеяний. Кого Аллах поведёт прямым путём, того никто уже не заблудит, а кого Аллах заблудит, того уже никто не поведёт прямым путём. Свидетельствую, что нет бога, кроме Аллаха, и что Мухаммад — Его раб и посланник, да благословит и приветствует Аллах Его, Его род и Его сподвижников.",{"mt":1.4}],["p","Я приступил к написанию этого исследования в 1426 (2005) году, когда Салих аль-Асмари начал призывать людей к тафуиду. Тогда я написал разъяснение основ тафуида, разъяснение убеждений первых поколений мусульман с цитатами из их книг и трудов, в которых они подтверждали смысл атрибутов Аллаха. Я не издавал эту работу, ограничившись распространением её среди некоторых интересующихся этой темой. Уже тогда я понял, что тафуид не был основной целью этого человека, это было лишь прикрытием. На самом деле этот еретик имел две цели:"],["p","• Введение в еретическую философскую идеологию. Если человек примет тафуид, считая его идеологией первых поколений мусульман, а затем свяжется с аллегорическим толкованием священных текстов, это приведёт его к тому, что он начнёт читать книги по рациональному богословию, возвеличивать их и их авторов и оставит книги учёных, подтверждавших атрибуты Аллаха. Между большинством суннитов и книгами рациональных богословов была всеобщая отстранённость и сильная неприязнь, но они поставили перед собой цель устранить это, чего и добились во время той смуты. Многие молодые люди заблудились в тех книгах, с которыми не были до этого знакомы."],["p","Тафуид распространялся для того, чтобы набросить тень сомнения на идеологию первых поколений мусульман, умалить величину их знания и понимания и заявить о том, что подтверждение"]],"notes":[]},{"n":12,"head":"МУХАММАД МАХМУД АЛЬ ХУДАЙР","side":"c","blocks":[["c","смысла атрибутов было перенято только от Ибн Таймии и небольшой группы его последователей, и что вся община либо аллегорически толкует атрибуты Аллаха, либо считает их смысл неизвестным."],["p","• Возрождение, поддержка и защита идеологии отрицания атрибутов Аллаха, обвинение суннитов в уподоблении Аллаха творениям и антропоморфизме, предостережение от них и запугивание. Дело дошло до того, что они начали обсуждать между собой, являемся ли мы верующими и можно ли совершать молитву позади нас. Всё это произошло в той смуте, в которой суннитам причинили страдания, а еретики-отрицатели атрибутов Аллаха получили распространение."],["p","Обвинение суннитов в уподоблении Аллаха творениям и ан-тропоморфизме — наследие, перенятое от джахмитов, ведь это они так называли суннитов.",{"mt":1.3}],["p","Сказал Исхак (237): «Признак Джахма и его последователей — обвинение суннитов в антропоморфизме. На самом деле, это джахмиты отрицают атрибуты Аллаха. И даже их самих можно назвать антропоморфистами»<sup>1</sup>."],["p","Сказал Абу Хатим ар-Рази (277): «Признак джахмитов — именование суннитов антропоморфистами»<sup>2</sup>."],["p","Сказал Абу Зура ар-Рази (264): «Отрицатели отвергают ат-рибуты Аллаха, которыми Он сам Себя описал в Коране и Сунне, и не принимают достоверные хадисы о Его атрибутах, истолковывают их своими неправильными мнениями в соответствии со своими заблудшими убеждениями и считают передатчиков этих хадисов антропоморфистами. Кто считает подтверждение атрибутов Господа из Корана и Сунны без уподобления и сравнения антропоморфизмом, тот является отрицателем Его атрибутов. И это их действие и является тому доказательством."]],"notes":[[1,"Аль-Лялякаи, 3/588."],[2,"«Акыдат ас-саляф», 303, аль-Лялякаи, 3/588."]]},{"n":13,"head":"ИДЕОЛОГИЯ ТАФУИДА","side":"c","blocks":[["c","Так говорили учёные, среди которых Ибн аль-Мубарак и Уаки»<sup>1</sup>."],["p","И эти люди пошли по пути своих предшественников, используя неоднозначные выражения, давая понять, что они возвеличивают Аллаха и отрицают от Него недостатки, но нет за ними ничего, кроме отрицания атрибутов Аллаха и лишения их смысла. Так они отрицали у Аллаха направление, объём, границу, явления, цели и изменения."],["p","Писал Ибн Таймия: «Мутазилиты говорили, что Аллах пречист от явлений, частей, изменений и границ, а преследовали этим отрицание атрибутов и действий Аллаха, Его отделённость от творений и возвышенность над Троном. Они употребляли по отношению к суннитам, подтверждающим атрибуты Аллаха, неоднозначные фразы, из которых люди понимали, что сунниты имеют неверные убеждения. Так, когда они говорили, что Аллах пречист от явлений, то внешне эта фраза выглядит правильной, потому что люди понимают из этого, что Он пречист от превращения и ухудшения, как это происходит с людьми в случае болезни и слабости. И нет сомнений, что Аллах пречист от этого. Однако их целью было сказать, что у Аллаха нет ни Знания, ни Могущества, ни Жизни, ни Речи, которую Он произнёс — ничего из тех атрибутов, которые они называют явлениями."],["p","Когда же они говорят, что Аллах пречист от границ, объёмов и направлений, то дают понять людям, что имеют в виду, что творения не ограничивают Его и не содержат Его в себе. И этот смысл верен. Однако их целью было сказать, что Аллах не отделён от своих творений, и что нет над небесами никакого господа, и нет на Троне никакого бога, и что Мухаммад (да благословит его Аллах и приветствует) не возносился к Нему, и что ничего от Него не спускается, и ничего к Нему не поднимается, и ничего к Нему не приближается, и не поднимаются к Нему руки во время мольбы и другие джахмитские взгляды."]],"notes":[[1,"«Аль-Худжа», 1/202."]]},{"n":14,"head":"МУХАММАД МАХМУД АЛЬ ХУДАЙР","side":"c","blocks":[["p","А когда они говорят, что Аллах не является телом, то дают понять людям, что Аллах не относится к творениям и не похож на тела творений. И этот смысл верен. Однако, их целью было сказать, что Аллаха невозможно увидеть, и что Он не разговаривает сам, и нет у Него никаких атрибутов, и что Он не отделён от творений и тому подобное."],["p","А когда они говорят, что в Аллахе не происходят явления, то дают понять людям, что хотят сказать, что Аллах не изменяется и не происходят с Ним те явления, которые происходят с творениями, изменяющие и ослабляющие их. И этот смысл верен. Однако, их целью было сказать, что нет у Аллаха действий, которые Он совершает сам и по своему выбору, и нет у Него Речи и действий, связанных с Его Волей и Могуществом, и что Аллах не может возвышаться, нисходить и приходить, и что не было при создании творений никакого действия от Него, но сами творения являются действием. То есть нет ни действия, ни того, на что оно направлено. Нет акта творения и нет сотворённого, но само сотворённое и есть акт творения, а то, на что направлено действие и есть действие и всё такое»<sup>1</sup>."],["p","Таково положение мутазилитов и джахмитов, и оппонент многое из их ложного наследия перенял. Он использовал те же фразы, чтобы добиться этим отрицания Возвышенности Аллаха сущностью, отрицания Речи Аллаха, состоящей из букв и звуков, отрицания действия, совершаемых по Его Желанию, и отрицанию большинства атрибутов Аллаха. Господь, по его мнению, не разговаривает, когда захочет, не гневается и не бывает довольным, не любит и не ненавидит, не нисходит и не приходит, не взошёл на Трон, не показывается никому из своих творений, нет у Него Рук, Хватки и Пальцев, Он не приближается к своему рабу и своим творениям, не поднимаются к Нему ангелы и не спускаются от Него Его Слова."],["p","И после всего этого они говорят, что не причастны к отрицанию атрибутов Аллаха. Что это за непричастность такая? Что это"]],"notes":[[1,"«Дар ат-тааруд», 2/13."]]},{"n":15,"head":"ИДЕОЛОГИЯ ТАФУИДА","side":"c","blocks":[["c","за подтверждение атрибутов и возвеличивание Аллаха, когда Он говорит, что Он взошёл на Трон, и что Он придёт в Судный День, и что Он показал Себя горе, и что разговаривал с Адамом, а затем и с Мусой, и что будет разговаривать с обитателями Рая, и что Он любит богобоязненных, благодетельных верующих и ненавидит неверующих и лицемеров, и что нисходит на ближнее небо, и что свернёт своей Правой Рукой небеса в Судный День, и что положит землю на свой Палец, а горы на другой Палец, и что Он милует, бывает довольным, гневается, удивляется и негодует, и всё это в прямом смысле, согласно устоявшейся языковой традиции и так, как это подобает Господу Величия и Почёта, а ты говоришь, что этого не было и не будет, это ан-тропоморфизм и ограничение Аллаха, неверие и богохульство? Ты считаешь, что это есть в Коране и Сунне лишь для того, чтобы не отвернуть от Аллаха язычников, а на самом деле Аллах не имеет таких атрибутов и только пропащий может описывать Его так."],["p","На что он опирается, описывая Господа, если нельзя опираться на Коран и Сунну, потому что явный смысл их текстов является неверием и невозможностью?"],["p","Сторонники аллегорического толкования считают, что опираться надо на разум и на то, что он подтвердит. А то, что разум считает невозможным, нужно отрицать. Разум указал им на семь атрибутов Аллаха, поэтому они подтверждают их, не выходя за их рамки и сводя остальные атрибуты к ним. Ведь они якобы отрицают от Аллаха недостатки и не причастны к ограничению Аллаха, уподоблению Его творениям и антропоморфизму."],["p","А адепты тафуида говорят, что подтверждают только то, что есть в Коране и Сунне: Руку, Пальцы, Восхождение, Нисхождение, Пришествие, Любовь, Милость, Гнев, Довольство Аллаха, однако смысл всех этих слов неизвестен. Они не склоняют эти слова и не переводят их на другие языки, ведь это лишь словесные формы, наподобие отдельных букв в начале некоторых сур, смысл которых неизвестен ни Мухаммаду (да благословит его"]],"notes":[]},{"n":16,"head":"МУХАММАД МАХМУД АЛЬ ХУДАЙР","side":"c","blocks":[["c","Аллах и приветствует), ни Джибрилю, ни сподвижникам и невозможно его узнать."],["p","А когда мы спрашиваем их, любит ли Аллах верующих, они отвечают, что не приписывают Аллаху Любовь в прямом смысле, ведь прямой смысл этого — симпатия к любимому, а это невозможно для Аллаха, но, возможно, смысл этого — желание вознаграждения или какой-то другой смысл, но не буквальный."],["p","А когда мы спрашиваем их доволен ли Аллах Мухаммадом (да благословит его Аллах и приветствует) и Его (да благословит его Аллах и приветствует) сподвижниками, давшими присягу под деревом, они отвечают, что прямой смысл Довольства невозможен по отношению к Аллаху, а что касается остальных значений, то они не утверждают точно, что имеется в виду какой-то конкретный из них, но может быть этот, а может быть тот."],["p","А когда мы спрашиваем их, взошёл ли Аллах на Трон, как Он сообщил об этом в своём Писании, то они отвечают, что Восхождение на Трон, в смысле возвышенности над чем-то, невозможно по отношению к Аллаху, а что касается остальных значений, то они возможны, однако они не конкретизируют ни один из них, но говорят <i>«истауа»</i>, не знают его смысла, и не говорят, что у Аллаха есть атрибут Восхождение на Трон."],["p","Но каждый разумный понимает, что нет разницы между вами и вашими единомышленниками: вы тоже не подтверждаете больше семи атрибутов. А поскольку вы не знаете смысла атрибутов Аллаха и отрицаете его, вы хуже сторонников аллегорического толкования."],["p","Сказал Хаммад Ибн Зейд: «Джахмиты подобны тем, которые говорят, что дома у них есть пальма. Их спрашивают:"],["p","— Есть ли у неё ветки?"],["p","— Нет."],["p","— Есть ли у неё кора?"],["p","— Нет."],["p","— Есть у неё финики и грозди?"],["p","— Нет."],["p","— У неё есть ствол?"]],"notes":[]},{"n":17,"head":"ИДЕОЛОГИЯ ТАФУИДА","side":"c","blocks":[["p","— Нет."],["p","— Тогда нет в вашем доме пальмы!»<sup>1</sup>"],["p","<b>УБЕЖДЕНИЯ ПЕРВЫХ ПОКОЛЕНИЙ</b>",{"mt":1.91}],["p","<b>МУСУЛЬМАН</b>"],["p","Если нам скажут, что мы отвергли аллегорическое толкование и тафуид и перешли границы, пороча их, и потребуют разъяснить убеждения первых поколений мусульман, то мы скажем, что не было у них никаких убеждений, помимо того, что в Коране и Сунне. И каждый атрибут, которым описал Себя Аллах, или описал им Его Посланник Аллаха (да благословит его Аллах и приветствует) — истина и правда, необходимо обязательно верить в это и быть убеждённым в том, что они относятся к Аллаху совершенным и прекрасным образом, будучи чистыми от любого проявления недостатка и изъяна. Ведь это атрибуты Великого, Прекрасного и Святого Господа. Для суннитов нет разницы между сущностными и смысловыми атрибутами, или теми, что устанавливает и разум, и шариатский текст, или теми, что утверждено лишь шариатским текстом: каждый атрибут Аллаха, достоверно установленный шариатским текстом, относится к Нему. Невозможно, чтобы Аллах описывал Себя, или описывал Его Посланник Аллаха (да благословит его Аллах и приветствует) тем, что невозможно по отношению к Нему, и невозможно, чтобы явный смысл слов Его Великого, Благородного и Славного Писания вёл к неверию. Аллах превыше этого! И невозможно, чтобы смысл атрибутов Аллаха, ниспосланных Им в Руководстве прямого пути и доведённых безошибочным Посланником (да благословит его Аллах и приветствует), был неизвестным или каким-то скрытым, противоречащим явному, вместе с тем, что не было дано разъяснения, предупреждения, предостережения, указания и руководства.",{"mt":1}]],"notes":[[1,"«Аль-Улюу», 250."]]},{"n":18,"head":"МУХАММАД МАХМУД АЛЬ ХУДАЙР","side":"c","blocks":[["p","Это и есть убеждения первых поколений мусульман. А что касается того, кто передаёт их убеждения из книг их идеологических оппонентов, в последствии пожалевших и раскаявшихся, то какое нам до него дело?"],["p","Учёные первых поколений не описывали бы своего Господа, если бы Он сам Себя не описал. Сказал Афлях Ибн Мухаммад: «Я сказал Ибн аль-Мубараку: „Мне не нравится описывать. Хватит описывать Господа“. И сказал ему Ибн аль-Мубарак: „Мне больше всех это не нравится, но если это описание есть в Коране и Сунне, то и мы осмеливаемся на это“»<sup>1</sup>. Сказал Ибн Таймия: «Ибн аль-Мубарак имел в виду, что он не любит описывать Аллаха от себя, если описания нет в Коране и Сунне»<sup>2</sup>."],["p","И мы говорим так же: «Если описание есть в Коране и Сунне, то и мы осмеливаемся на это». И как сказал Ахмад: «Мы говорим так же, как сказал Аллах, и описываем Его тем, чем Он сам Себя описал. Не переходим эти границы и не отменяем какой-либо из атрибутов, если кому-то кажется в нём недостаток»<sup>3</sup>."],["p","Если кто-то скажет нам, что какой-либо атрибут содержит в себе уподобление Аллаха творениям, антропоморфизм или невозможность, то мы скажем, что это не мы описали Аллаха так, а Он сам Себя описал."],["p","Писал аз-Захаби: «Ибн Фурак пришёл к султану Махмуду Ибн Субуктикину и сказал: „Нельзя описывать Аллаха Возвышенностью, так как получится, что Он и внизу. Кто позволяет себе сказать о Нём, что Он наверху, тот должен считать дозволенным сказать о Нём, что Он внизу“. И тогда султан сказал: „Это не я описал Его Возвышенностью, чтобы это обязывало меня считать так, но Он сам Себя описал“. И тогда Ибн Фурак растерялся, а когда вышел от султана, умер. Говорили, что его желчный пузырь лопнул»<sup>4</sup>."]],"notes":[[1,"Аль-Лялякаи, 2/210."],[2,"«Маджму аль-фатауа», 5/51."],[3,"«Тахрим ан-назар», 39."]]},{"n":19,"head":"ИДЕОЛОГИЯ ТАФУИДА","side":"c","blocks":[["p","<b>О КНИГЕ «СОВЕРШЕННЫЕ СЛОВА»</b>"],["p","Среди последствий вышеуказанной смуты было то, что некоторые искатели знания сошли с правильного пути первых поколений мусульман, подхватили взгляды отрицателей атрибутов Аллаха и принялись искать различные слова то там, то здесь, в поддержку своей идеологии и в помощь своих ложных взглядов. Среди таких был и наш брат Сейф аль-Асри. И дошли до меня некоторые его слова о тафуиде, вместе с тем, что внешне он возвеличивал первые поколения верующих и не говорил о тех вопросах, на которые я указал выше, таких как Возвышенность Аллаха, Его Речь и действия. Затем какое-то время я не следил за ним, пока не наткнулся на его книгу «Совершенные слова» и обнаружил в них порочение суннитов и сеяние смуты, что не могло прийти мне в голову, громкие обвинения их в уподоблении Аллаха творениям и антропоморфизме, явное отрицание Возвышенности Аллаха сущностью и обвинение тех, кто подтверждает его, в ограничении Аллаха и приписывании Ему тела и даже в пантеизме. Затем он абсолютно неверно приписал тафуид группе имамов, среди которых Абу Ханифа, Малик, Ибн аль-Мубарак, аш-Шафии, Ахмад, ат-Тирмизи, Ибн Хузейма, Ибн Абдульбарр, аль-Багауи, Ибн Касир, Ибн Раджаб и другие. Его книга была переполнена фразами, которые неизвестны суннитам, типа «конечность», «орган», «часть». Он обязывал своих оппонентов принять, что это якобы вытекает из их взглядов. Он заявил, что невозможно подтверждать Руку и Лик Аллаха в прямом смысле, если это не будет органом. И больше всего он высказывался пренебрежительно и вызывающе о понимании смысла Лика и Руки Аллаха и чинил этому препятствия. И удивительно как скрылись его искажения, ухищрения и ложные доводы в его книге для тех обладателей знания, которые написали к ней свои рецензии.",{"mt":1}]],"notes":[[4,"«Ас-Сияр», 17/487."]]},{"n":20,"head":"МУХАММАД МАХМУД АЛЬ ХУДАЙР","side":"c","blocks":[["p","Он привёл чересчур много цитат ашаритов, дозволявших тафуид и аллегорическое толкование, утверждающих, что ранние учёные не знали смысла атрибутов Аллаха. В этом сошлись два преступления: ложь на первые поколения, ведь они не исповедовали тафуид; и дозволение аллегорического толкования, который запрещали первые поколения. Их порицание и запрет ал-легорического толкования — дело известное и бесспорное, не один учёный передал их единогласие на это. Более того, это единогласие неоднократно можно встретить на страницах «Совершенных слов»! Автор утверждает, что запретное аллегорическое толкование — это неправильное толкование мутазилитов. Мы опровергнем это и покажем, что аллегорическое толкование ашаритов — то же, что и толкование мутазилитов. И что дают многочисленные цитаты ашаритов, кроме бесполезного удлинения книги? И разве передаётся идеология тех, чьи книги доступны, из книг представителей другой идеологии?"],["p","Многие братья настойчиво просили меня завершить и выпустить исследование о тафуиде и опровергнуть нашего брата Сейфа аль-Асри. Некоторое время я был занят другими делами, а затем появился шанс, и я воспользовался им и рассмотрел приведённые в его книге тезисы, сомнения и цитаты. Читатель увидит, что раздел с цитатами — самый объёмный в этом исследовании, и это из-за моего стремления показать непричастность имамов к тафуиду, который он к ним приписал. Также я убеждён в том, что подтвердить либо опровергнуть заявление о том, что ранние учёные не знали смысла атрибутов Аллаха, возможно лишь путём приведения достоверных цитат от них самих."],["p","<b>МЕТОДОЛОГИЯ ИССЛЕДОВАНИЯ</b>",{"mt":1.9}],["p","При написании исследования, я пользовался уже существующими работами, например, книгой «Идеология сторонников тафуида» доктора Ахмада аль-Кады, а также некоторыми работами из интернета, например, исследованием Мухаммада ар-Раббаха «Тафуид в атрибутах Аллаха». Да воздаст им Аллах",{"mt":1}]],"notes":[]},{"n":21,"head":"ИДЕОЛОГИЯ ТАФУИДА","side":"c","blocks":[["c","благом за их усердие. Также я выражаю большую благодарность каждому, кто прочтёт эту книгу и поможет мне своими примечаниями."],["p","Прошу Аллаха сделать мою работу искренней ради Его Благородного Лика и простить за допущенные в ней упущения и ошибки."],["p","Да благословит и приветствует Аллах Мухаммада, Его род и сподвижников."],["p","Написал: Мухаммад Ибн Махмуд аль Худайр",{"mt":1}],["p","Четверг, 11 Раби аль-Ахир, 1437"]],"notes":[]}];
